// Validation et préparation des données webhook
const webhookData = $input.item.json.body || $input.item.json;

console.log('🔍 Données reçues:', JSON.stringify(webhookData, null, 2));

// Validation des champs requis
if (!webhookData || typeof webhookData !== 'object') {
  throw new Error('Données webhook invalides');
}

if (!webhookData.contenu) {
  throw new Error('Champ "contenu" manquant');
}

// Traitement des URLs d'images
let imageUrls = [];
if (webhookData.image_urls) {
  if (typeof webhookData.image_urls === 'string') {
    // Format string CSV
    imageUrls = webhookData.image_urls
      .split(',')
      .map(url => url.trim())
      .filter(url => url && url.startsWith('http'));
  } else if (Array.isArray(webhookData.image_urls)) {
    // Format array
    imageUrls = webhookData.image_urls
      .filter(url => url && typeof url === 'string' && url.startsWith('http'));
  }
}

console.log(`✅ ${imageUrls.length} image(s) détectée(s)`);

return {
  json: {
    contenu: webhookData.contenu,
    image_urls: imageUrls,
    image_count: imageUrls.length,
    timestamp: new Date().toISOString()
  }
};

// Fusion et préparation finale pour Flask
const validationData = $node["🔍 Validation Données"].json;
const aiResponse = $input.item.json;

console.log('🤖 Réponse OpenAI brute:', JSON.stringify(aiResponse, null, 2));

// Extraction de l'analyse IA selon le format de réponse
let aiAnalysis = {
  title: "Titre par défaut",
  subtitle: "Sous-titre par défaut",
  body: validationData.contenu
};

try {
  let aiContent = null;

  // Gestion des différents formats de réponse OpenAI
  if (typeof aiResponse === 'string') {
    aiContent = aiResponse;
  } else if (Array.isArray(aiResponse) && aiResponse[0]?.message?.content) {
    aiContent = aiResponse[0].message.content;
  } else if (aiResponse?.message?.content) {
    aiContent = aiResponse.message.content;
  } else if (aiResponse?.content) {
    aiContent = aiResponse.content;
  }

  if (aiContent) {
    // Nettoyage et parsing
    const cleanJson = aiContent
      .replace(/```json\n?|```\n?/g, '')
      .trim();

    const parsed = JSON.parse(cleanJson);

    if (parsed.title) aiAnalysis.title = parsed.title;
    if (parsed.subtitle) aiAnalysis.subtitle = parsed.subtitle;
    if (parsed.body) aiAnalysis.body = parsed.body;

    console.log('✅ Analyse IA extraite avec succès');
  }
} catch (error) {
  console.log('⚠️ Fallback sur valeurs par défaut:', error.message);
}

// Utiliser le template sélectionné par l'utilisateur
const imageCount = validationData.image_count;
let template = validationData.template || 'Magazine art template page 1.idml'; // Template choisi par l'utilisateur

console.log(`📋 Template sélectionné par l'utilisateur: ${template} pour ${imageCount} image(s)`);

// Préparation de la payload finale
return {
  json: {
    // Données pour Flask
    prompt: aiAnalysis.title,
    text_content: aiAnalysis.body,
    subtitle: aiAnalysis.subtitle,
    template: template,
    image_urls: validationData.image_urls,

    // Métadonnées pour traçabilité
    metadata: {
      image_count: imageCount,
      template_used: template,
      processed_at: new Date().toISOString(),
      ai_extraction_success: aiAnalysis.title !== "Titre par défaut"
    }
  }
};

// Préparation de la réponse de succès
const flaskResponse = $input.item.json;
const metadata = $node["🔗 Fusion & Préparation"].json.metadata;

const projectId = flaskResponse.project_id || 'unknown';
const downloadUrl = `http://host.docker.internal:5003/api/download/${projectId}`;

return {
  json: {
    status: 'success',
    message: '🎉 Document InDesign créé avec succès!',
    project_id: projectId,
    download_url: downloadUrl,
    details: {
      template_used: metadata.template_used,
      image_count: metadata.image_count,
      processed_at: metadata.processed_at,
      ai_analysis_success: metadata.ai_extraction_success
    },
    instructions: {
      download: `Téléchargez votre document: ${downloadUrl}`,
      preview: 'Le document contient votre article formaté avec les images intégrées'
    }
  }
};

// Gestion des erreurs avec détails
const error = $input.item.json;
const originalData = $node["🔍 Validation Données"].json;

let errorMessage = 'Erreur inconnue lors de la création du document';
let errorDetails = {};

if (error.error) {
  errorMessage = error.error;
}

if (error.message) {
  errorMessage = error.message;
}

errorDetails = {
  flask_response: error,
  original_request: {
    had_content: !!originalData.contenu,
    image_count: originalData.image_count
  },
  timestamp: new Date().toISOString()
};

return {
  json: {
    status: 'error',
    message: `❌ ${errorMessage}`,
    error_details: errorDetails,
    suggestions: [
      'Vérifiez que le serveur Flask est accessible',
      'Assurez-vous que les URLs d\'images sont valides',
      'Confirmez que le template existe'
    ]
  }
};
